 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** The only actor allowed to carry out a recovery action. */
export type ErrorRecoveryScope = 'self' | 'user';

/** A bounded target understood by the UI; it is never an executable value. */
export type ErrorNextActionTarget =
  | 'authentication'
  | 'billing'
  | 'configuration'
  | 'conversation'
  | 'model'
  | 'permissions';

ex**
 * Declarative recovery verbs. No command, script, shell, executable, or argv
 * data is accepted here.
 */
export type ErrorNextAction =
  | { kind: 'retry' }
  | { kind: 'reauthenticate'; target: 'authentication' }
  | { kind: 'reconfigure'; target: ErrorNextActionTarget }
  | { kind: 'open-settings'; target: ErrorNextActionTarget }
  | { kind: 'contact-support' };

export type AppErrorRecovery = {
  retryable: boolean;
  scope: ErrorRecoveryScope;
  nextAction?: ErrorNextAction;
};

/**
 * Stable recovery policy for every error class. `self` is reserved for safe,
 * bounded self-retry. All other classes require a user action; UNKNOWN has no
 * action because there is no honest automatic repair to advertise.
 */
export const APP_ERROR_RECOVERY: Record<AppErrorCode, AppErrorRecovery> = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'contact-support' },
  },
  TIMEOUT: { retryable: true, scope: 'self', nextAction: { kind: 'retry' } },
  RATE_LIMIT: { retryable: true, scope: 'self', nextAction: { kind: 'retry' } },
  PERMISSION: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'open-settings', target: 'permissions' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'configuration' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'conversation' },
  },
  NETWORK: { retryable: true, scope: 'self', nextAction: { kind: 'retry' } },
  CONFIG: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'configuration' },
  },
  GATEWAY: { retryable: true, scope: 'self', nextAction: { kind: 'retry' } },
  BILLING: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'open-settings', target: 'billing' },
  },
  OVERLOADED: { retryable: true, scope: 'self', nextAction: { kind: 'retry' } },
  MODEL_NOT_FOUND: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'model' },
  },
  // The raw error must be exposed to the user. Inventing a repair would be
  // misleading, so this entry deliberately has no nextAction.
  UNKNOWN: { retryable: false, scope: 'user' },
