 *
 * Classification reads these first; it only falls back to the raw technical
 * message when none of them identify a class. A user-facing string that has
 * already been translated is never a classification input (issue #120), so
 * changing the display language can never change the class.
 */
export type ErrorSignals = {
  code?: string;
  status?: number;
  reason?: string;
};

/**
 * Provider `code`/`reason`/`type` tokens (normalized to upper case) mapped to a
 * class. One table serves both structured fields so the two can never drift.
 */
const CODE_SIGNALS: Record<string, AppErrorCode> = {
  TIMEOUT: 'TIMEOUT',
  REQUEST_TIMEOUT: 'TIMEOUT',
  PERMISSION: 'PERMISSION',
  PERMISSION_ERROR: 'PERMISSION',
  FORBIDDEN: 'PERMISSION',
  PERMISSION_DENIED: 'PERMISSION',
  GATEWAY: 'GATEWAY',
  VALIDATION: 'CONFIG',
  INVALID_REQUEST: 'CONFIG',
  INVALID_REQUEST_ERROR: 'CONFIG',
  UNSUPPORTED: 'CHANNEL_UNAVAILABLE',
  CHANNEL_UNAVAILABLE: 'CHANNEL_UNAVAILABLE',
  CONVERSATION_STATE: 'CONVERSATION_STATE',
  INVALID_CONVERSATION_STATE: 'CONVERSATION_STATE',
  NETWORK: 'NETWORK',
  CONNECTION_ERROR: 'NETWORK',
  AUTH_INVALID: 'AUTH_INVALID',
  UNAUTHORIZED: 'AUTH_INVALID',
  AUTH_EXPIRED: 'AUTH_INVALID',
  AUTHENTICATION_ERROR: 'AUTH_INVALID',
  AUTH_PERMANENT: 'AUTH_PERMANENT',
  INVALID_API_KEY: 'AUTH_PERMANENT',
  API_KEY_INVALID: 'AUTH_PERMANENT',
  KEY_REVOKED: 'AUTH_PERMANENT',
  RATE_LIMIT: 'RATE_LIMIT',
  RATE_LIMITED: 'RATE_LIMIT',
  RATE_LIMIT_EXCEEDED: 'RATE_LIMIT',
  TOO_MANY_REQUESTS: 'RATE_LIMIT',
  BILLING: 'BILLING',
  PAYMENT_REQUIRED: 'BILLING',
  INSUFFICIENT_BALANCE: 'BILLING',
  INSUFFICIENT_QUOTA: 'BILLING',
  QUOTA_EXCEEDED: 'BILLING',
  BILLING_HARD_LIMIT_REACHED: 'BILLING',
  OVERLOADED: 'OVERLOADED',
  OVERLOADED_ERROR: 'OVERLOADED',
  MODEL_OVERLOADED: 'OVERLOADED',
  SERVER_OVERLOADED: 'OVERLOADED',
  MODEL_NOT_FOUND: 'MODEL_NOT_FOUND',
  UNKNOWN_MODEL: 'MODEL_NOT_FOUND',
};

const STATUS_SIGNALS: Record<number, AppErrorCode> = {
  401: 'AUTH_INVALID',
  402: 'BILLING',
  403: 'PERMISSION',
  408: 'TIMEOUT',
  429: 'RATE_LIMIT',
  503: 'OVERLOADED',
  504: 'TIMEOUT',
  529: 'OVERLOADED',
};

export function mapBackendErrorCode(code?: string): AppErrorCode {
  if (typeof code !== 'string') return 'UNKNOWN';
  return CODE_SIGNALS[code.trim().toUpperCase()] ?? 'UNKNOWN';
}

/**
 * Last-resort classification from the untranslated technical message.
 * Only reachable when no structured signal identified a class.
 */
function classifyMessage(message: string): AppErrorCode {
  // Separator-insensitive so `invalid_api_key` / `rate_limit_exceeded` style
  // provider tokens match the same probes as prose.
  const lower = message.toLowerCase().replace(/[_-]+/g, ' ');

  if (
    lower.includes('invalid ipc channel')
    || lower.includes('no handler registered')
    || lower.includes('window is not defined')
    || lower.includes('unsupported')
  ) {
    return 'CHANNEL_UNAVAILABLE';
  }
  if (lower.includes('conversation state') || lower.includes('roles must alternate')) {
    return 'CONVERSATION_STATE';
  }
  if (
    lower.includes('insufficient balance')
    || lower.includes('insufficient_quota')
    || lower.includes('insufficient quota')
    || lower.includes('quota exceeded')
    || lower.includes('exceeded your current quota')
    || lower.includes('billing')
    || lower.includes('credit balance')
    || lower.includes('payment required')
  ) {
    return 'BILLING';
  }
  if (
    lower.includes('invalid api key')
    || lower.includes('api key is invalid')
    || lower.includes('api key was revoked')
    || lower.includes('key has been revoked')
  ) {
    return 'AUTH_PERMANENT';
  }
  if (
    lower.includes('invalid authentication')
    || lower.includes('unauthorized')
    || lower.includes('auth failed')
    || lower.includes('401')
  ) {
    return 'AUTH_INVALID';
  }
  if (lower.includes('model not found') || lower.includes('unknown model')) {
    return 'MODEL_NOT_FOUND';
  }
  if (lower.includes('overloaded')) {
    return 'OVERLOADED';
  }
  if (lower.includes('timeout') || lower.includes('timed out') || lower.includes('abort')) {
    return 'TIMEOUT';
  }
  if (lower.includes('rate limit') || lower.includes('429')) {
    return 'RATE_LIMIT';
  }
  if (
    lower.includes('permission')
    || lower.includes('forbidden')
    || lower.includes('denied')
    || lower.includes('403')
  ) {
    return 'PERMISSION';
  }
  if (
    lower.includes('network')
    || lower.includes('fetch')
    || lower.includes('econnrefused')
    || lower.includes('econnreset')
    || lower.includes('enotfound')
  ) {
    return 'NETWORK';
  }
  if (lower.includes('gateway')) {
    return 'GATEWAY';
  }
  if (lower.includes('config') || lower.includes('invalid') || lower.includes('validation') || lower.includes('400')) {
    return 'CONFIG';
  }

  return 'UNKNOWN';
}

function readStringField(source: Record<string, unknown>, key: string): string | undefined {
  const value = source[key];
  if (typeof value === 'string' && value.trim()) return value.trim();
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  return undefined;
}

function readStatusField(source: Record<string, unknown>, key: string): number | undefined {
  const value = source[key];
  const parsed = typeof value === 'number'
    ? value
    : (typeof value === 'string' && /^\d+$/.test(value.trim()) ? Number(value.trim()) : Number.NaN);
  if (!Number.isFinite(parsed) || parsed < 100 || parsed > 599) return undefined;
  return parsed;
}

/** Walks the error and its nested cause/response/data chain once. */
function collectSignalSources(err: unknown): Array<Record<string, unknown>> {
  const sources: Array<Record<string, unknown>> = [];
  const seen = new Set<unknown>();
  const visit = (value: unknown): void => {
    if (!value || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);
    const record = value as Record<string, unknown>;
    sources.push(record);
    visit(record.cause);
    visit(record.error);
    visit(record.response);
    visit(record.data);
  };
  visit(err);
  return sources;
}

/**
 * Reads structured signals, most explicit source first: caller-supplied
 * `details` (host-api envelopes, store context) then the throwing object and
 * its nested cause/response chain.
 */
export function readErrorSignals(err: unknown, details?: Record<string, unknown>): ErrorSignals {
  const sources = [...(details ? [details] : []), ...collectSignalSources(err)];
  const signals: ErrorSignals = {};
  for (const source of sources) {
    signals.code ??= readStringField(source, 'code')
      ?? readStringField(source, 'errorCode')
      ?? readStringField(source, 'reasonCode');
    signals.status ??= readStatusField(source, 'status')
      ?? readStatusField(source, 'statusCode')
      ?? readStatusField(source, 'httpStatus');
    signals.reason ??= readStringField(source, 'reason')
      ?? readStringField(source, 'type')
      ?? readStringField(source, 'errorType');
  }
  return signals;
}

function classifySignals(signals: ErrorSignals): AppErrorCode | undefined {
  for (const token of [signals.code, signals.reason]) {
    if (!token) continue;
    const mapped = mapBackendErrorCode(token);
    if (mapped !== 'UNKNOWN') return mapped;
  }
  return signals.status !== undefined ? STATUS_SIGNALS[signals.status] : undefined;
}

function readErrorMessage(err: unknown): string {
  if (err instanceof Error) return err.message;
  if (err && typeof err === 'object') {
    return readStringField(err as Record<string, unknown>, 'message') ?? '';
  }
  return err === undefined || err === null ? '' : String(err);
}

export function normalizeAppError(err: unknown, details?: Record<string, unknown>): AppError {
  if (err instanceof AppError) {
    const requestId = err.requestId
      ?? readStringField(err.details ?? {}, 'requestId');
    return new AppError(
      err.code,
      err.message,
      err.cause ?? err,
      { ...(err.details ?? {}), ...(details ?? {}) },
      requestId,
    );
  }

  const message = readErrorMessage(err);
  const signals = readErrorSignals(err, details);
  // Structured signals win. Only their absence lets the untranslated technical
  // message (or a structured `reason` string) decide the class.
  const code = classifySignals(signals)
    ?? classifyMessage([signals.reason ?? '', message].join(' ').trim());
  return new AppError(
    code,
    message,
    err,
    details,
    readStringField(details ?? {}, 'requestId'),
  );
}
"},{"path":"harness/specs/tasks/harness-gap-error-recovery-next-action.md","content":"# G01 — Error recovery and bounded next actions

## Goal

Every `AppErrorCode` has one stable recovery policy containing `retryable`, an actor `scope`, and an optional declarative `nextAction`. The existing `AppError`/`HostResponse` envelope remains the only error envelope.

## Contract

- Recovery policy source of truth: `APP_ERROR_RECOVERY` in `src/lib/error-model.ts`.
- Every value in `APP_ERROR_CODES` has exactly one policy entry.
- `retryable: true` is permitted only for transient self-recovery classes. Such an entry has `scope: 'self'` and the action is exactly `{ kind: 'retry' }`.
- A non-retryable entry has `scope: 'user'` and must not have a retry action.
- `UNKNOWN` is not retryable and deliberately has no action. The raw error must be exposed to the user instead of claiming a repair.
- `AppError.retryable` and `AppError.nextAction` are derived from the policy for its stable `code`.

## Allowed action vocabulary

The only action kinds are:

- `retry`
- `reauthenticate`
- `reconfigure`
- `open-settings`
- `contact-support`

An action has only `kind` and, where needed, the bounded `target` value. Targets are semantic identifiers, never executable data. The model does not accept or emit `command`, `script`, `shell`, `exec`, `argv`, or similar fields.

## Recovery matrix

| Code | Retryable | Scope | Next action |
| --- | --- | --- | --- |
| `AUTH_INVALID` | no | user | `reauthenticate(authentication)` |
| `AUTH_PERMANENT` | no | user | `contact-support` |
| `TIMEOUT` | yes | self | `retry` |
| `RATE_LIMIT` | yes | self | `retry` |
| `PERMISSION` | no | user | `open-settings(permissions)` |
| `CHANNEL_UNAVAILABLE` | no | user | `reconfigure(configuration)` |
| `CONVERSATION_STATE` | no | user | `reconfigure(conversation)` |
| `NETWORK` | yes | self | `retry` |
| `CONFIG` | no | user | `reconfigure(configuration)` |
| `GATEWAY` | yes | self | `retry` |
| `BILLING` | no | user | `open-settings(billing)` |
| `OVERLOADED` | yes | self | `retry` |
| `MODEL_NOT_FOUND` | no | user | `reconfigure(model)` |
| `UNKNOWN` | no | user | none; expose the raw error |

## Verification

1. Exhaustively assert that the policy keys equal `APP_ERROR_CODES`.
2. Assert the retry invariant and the exact retry action shape.
3. Assert all action kinds and object keys belong to the bounded vocabulary.
4. Assert `UNKNOWN.nextAction` is absent.
5. Exercise ordinary, malformed, and already-normalized errors and verify the unified error envelope is unchanged.
"},{"path":"docs/dev/harness-gap-closure/g01-error-recovery-next-action.md","content":"# G01 closure: error recovery and next action

## Summary

`src/lib/error-model.ts` now assigns every `AppErrorCode` a stable recovery policy through the exhaustive `APP_ERROR_RECOVERY` record. `AppError` exposes the policy as `retryable` and `nextAction` while retaining its existing constructor, fields, and normalization behavior.

No parallel error type or response envelope was introduced. `normalizeAppError` continues to return `AppError`, and host response serialization can continue to use the existing `HostResponse` path.

## Policy

Only transient classes are marked retryable: `TIMEOUT`, `RATE_LIMIT`, `NETWORK`, `GATEWAY`, and `OVERLOADED`. Their scope is `self`, and their action is exactly `{ kind: 'retry' }`.

Every other class is non-retryable and belongs to the `user` scope. `UNKNOWN` remains in that scope but intentionally has no action: the renderer must expose the original error rather than manufacture a repair.

## Safe action model

`nextAction` is a declarative UI instruction, not an operation. Its allowed kinds are:

- `retry`
- `reauthenticate`
- `reconfigure`
- `open-settings`
- `contact-support`

Objects contain only `kind` and optionally one bounded semantic `target`. They cannot contain commands, scripts, shell text, executables, argument arrays, or arbitrary payload values.

## Consumer guidance

Consumers must use the scope to constrain who may perform the action. A `self` action may be offered only through the host's bounded retry mechanism. A `user` action must be presented as a user-facing choice. When `nextAction` is absent, show the original error and any available correlation ID; do not infer a repair from the error message.

## Compatibility

The public constructor signature and `AppError` properties are unchanged. New recovery fields are derived from the stable error code, so normalizing an existing `AppError` preserves its classification and produces the same recovery policy. Existing callers that only use `code`, `message`, `cause`, `details`, and `requestId` continue to work unchanged.
"}]}

