  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
